def kleene_iterate(f, bot=0.0, tol=1e-12, max_iter=10000):
    x = bot
    for i in range(max_iter):
        x_new = f(x)
        if abs(x_new - x) < tol:
            return x_new, i+1
        x = x_new
    return x, max_iter

def diagonal_fixed_point(phi, bot=0.0, tol=1e-12):
    def diagonal(x):
        return phi(x, x)
    return kleene_iterate(diagonal, bot, tol)

def simulation_depth(f, x, bot=0.0, max_depth=1000):
    val = bot
    for n in range(max_depth + 1):
        if val >= x - 1e-10:
            return n
        val = f(val)
    return None
